local function _ngafsfwz(s,cnt)local o={}for i=0,cnt-1 do local p=i*4+1 o[i+1]=byte(s,p)+byte(s,p+1)*256+byte(s,p+2)*65536+byte(s,p+3)*16777216 end return o end local function _ojouqjdnm(w)local o={}for i=1,#w do local v=w[i]o[i]=char(v%256,rs(v,8)%256,rs(v,16)%256,rs(v,24)%256)end return concat(o)end
local function _slyjycnb(x,a,b,c,d)x[a]=(x[a]+x[b])%4294967296 x[d]=lr(bx(x[d],x[a]),16)x[c]=(x[c]+x[d])%4294967296 x[b]=lr(bx(x[b],x[c]),12)x[a]=(x[a]+x[b])%4294967296 x[d]=lr(bx(x[d],x[a]),8)x[c]=(x[c]+x[d])%4294967296 x[b]=lr(bx(x[b],x[c]),7)end local function _umerianb(x)for _=1,10 do _slyjycnb(x,1,5,9,13)_slyjycnb(x,2,6,10,14)_slyjycnb(x,3,7,11,15)_slyjycnb(x,4,8,12,16)_slyjycnb(x,1,6,11,16)_slyjycnb(x,2,7,12,13)_slyjycnb(x,3,8,9,14)_slyjycnb(x,4,5,10,15)end end
